'use strict';
// One stable object ID and illustration per concept. Category repeats and synonyms are references.
const vocabularyObjects=new Map(vocabularyData.objects.map(o=>[o.id,o]));
const vocabularyCategories=new Map(vocabularyData.categories.map(c=>[c.id,c]));
let vocabularySaved=[];try{const v=JSON.parse(localStorage.getItem('spotmatch-vocabulary-saved-v1')||'[]');if(Array.isArray(v))vocabularySaved=v.filter(id=>vocabularyObjects.has(id));}catch{}
let vocabularySearchTimer=null;let vocabularyState=null,vocabularyFilter={category:'',query:'',saved:false,page:0,names:true};
const vocabularyModes=['explore','find','collect','pairs','sort'];
const vocabularyModeLabels={explore:'Meet the words',find:'Find a picture',collect:'Make a picture collection',pairs:'Picture partners',sort:'Two little collections'};
const vocabularyLegacyPicture=pictureIcon;pictureIcon=function(id,...args){if(typeof id==='string'&&id.startsWith('vocab:'))return vocabularyPicture(id.slice(6));return vocabularyLegacyPicture(id,...args);};
for(const item of vocabularyData.objects)friendlyNames['vocab:'+item.id]=item.label;
function vocabularyPicture(id){const o=vocabularyObjects.get(id);if(!o)throw Error('Unknown vocabulary object '+id);return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120" role="img" aria-label="${senEscape(o.label)}"><title>${senEscape(o.label)}</title><image href="${o.image}?v=${o.revision||'1'}" x="0" y="0" width="120" height="120"/></svg>`;}
function vocabularyImage(id,extra=''){const o=vocabularyObjects.get(id);return `<img src="${o.image}?v=${o.revision||'1'}" alt="${senEscape(o.label)}" width="240" height="240" ${extra}>`;}
function vocabularySetSaved(id){vocabularySaved=vocabularySaved.includes(id)?vocabularySaved.filter(v=>v!==id):[...vocabularySaved,id];try{localStorage.setItem('spotmatch-vocabulary-saved-v1',JSON.stringify(vocabularySaved));}catch{}}
function vocabularyWrite(hash){if(location.hash!==hash)history.pushState(null,'',location.pathname+hash);}
function vocabularyCategoryIds(category){return [...new Set(vocabularyCategories.get(category)?.entries.map(e=>e.objectId)||[])];}
function vocabularySample(category,n=4,offset=0){const ids=vocabularyCategoryIds(category);return Array.from({length:Math.min(n,ids.length)},(_,i)=>ids[(offset+i)%ids.length]);}
function vocabularyCard(id){const o=vocabularyObjects.get(id);return `<article class="vocabulary-card"><button class="vocabulary-open" data-vocab-open="${id}" aria-label="Explore ${senEscape(o.label)}">${vocabularyImage(id,'loading="lazy"')}<b ${vocabularyFilter.names?'':'class="vocabulary-name-hidden"'}>${senEscape(o.label)}</b></button><button class="vocabulary-save" data-vocab-save="${id}" aria-pressed="${vocabularySaved.includes(id)}" aria-label="${vocabularySaved.includes(id)?'Remove':'Save'} ${senEscape(o.label)}">${vocabularySaved.includes(id)?'★':'☆'}</button></article>`;}
function vocabularyLibrary(options={}){clearTimeout(vocabularySearchTimer);skillContext=null;skillFreePlay=false;prLibraryMode=false;Object.assign(vocabularyFilter,options);const f=vocabularyFilter,category=f.saved?null:vocabularyCategories.get(f.category),query=f.query.trim().toLocaleLowerCase();let ids=f.saved?[...vocabularySaved]:category?vocabularyCategoryIds(category.id):vocabularyData.objects.map(o=>o.id);if(query)ids=ids.filter(id=>{const o=vocabularyObjects.get(id);return [o.label,...o.aliases].some(word=>word.toLocaleLowerCase().includes(query));});const total=ids.length,size=36,pages=Math.max(1,Math.ceil(total/size));f.page=Math.min(Math.max(0,f.page),pages-1);const shown=ids.slice(f.page*size,(f.page+1)*size);app.innerHTML=`<section class="vocabulary-library"><div class="skill-crumb"><button class="back" id="vocabBack">← All skills</button><span>EVERYDAY WORDS, REAL OBJECTS</span></div><div class="vocabulary-hero"><div><span class="eyebrow">OUR OBJECT PICTURE LIBRARY</span><h1>So many things to name.</h1><p><b>${vocabularyData.objectCount.toLocaleString()} different object illustrations</b>, across 100 everyday categories. Repeated words share one picture.</p><p class="micro">Name the pictures together using speech, signs, or AAC. No generated voice or spoken answer is required.</p></div><div class="vocabulary-hero-pictures">${['sofa','bicycle','toothbrush','umbrella','apple','guitar'].filter(id=>vocabularyObjects.has(id)).map(id=>vocabularyImage(id)).join('')}</div></div><div class="vocabulary-toolbar"><label>Find a word<input id="vocabSearch" type="search" value="${senEscape(f.query)}" placeholder="For example: whisk, bus, toothpaste" autocomplete="off"></label><label>Choose a category<select id="vocabCategory"><option value="">All ${vocabularyData.objectCount.toLocaleString()} objects</option>${vocabularyData.categories.map(c=>`<option value="${c.id}" ${c.id===f.category?'selected':''}>${c.name}</option>`).join('')}</select></label><button class="secondary" id="vocabSaved" aria-pressed="${f.saved}">${f.saved?'Show all words':'★ Saved words ('+vocabularySaved.length+')'}</button><button class="secondary" id="vocabNames" aria-pressed="${f.names}">${f.names?'Hide written names':'Show written names'}</button></div><section class="vocabulary-category-intro"><div><h2>${f.saved?'Words you saved':category?category.name:query?'Search results':'Explore the objects'}</h2><p>${total} different picture${total===1?'':'s'}${category?' in this category':''}. ${category?'Some objects also belong in other categories.':'Open a picture for a large view, word forms, and practice.'}</p></div>${category?`<div class="vocabulary-play-buttons"><button class="primary" id="vocabExplore">Meet these words →</button><button class="secondary" id="vocabPlay">Play with these pictures →</button></div>`:''}</section><div class="vocabulary-grid">${shown.length?shown.map(vocabularyCard).join(''):'<p class="vocabulary-empty">No pictures here yet. Try a different word or category, or save a picture with its star.</p>'}</div><div class="vocabulary-pagination"><button class="secondary" id="vocabPrevious" ${f.page===0?'disabled':''}>← Previous pictures</button><span>Page ${f.page+1} of ${pages}</span><button class="primary" id="vocabNext" ${f.page+1>=pages?'disabled':''}>More pictures →</button></div><details class="quiet-notes"><summary>How to use this library</summary><p>Start with familiar objects and the child’s interests. Name an object while showing it, then look for or use a real example together. Accept pointing, sign, speech, or AAC. The stars make a small reusable word set; they are not a test score.</p><p>The list includes both common and more specialised words. Some look-alike objects need explanation or context. A picture alone does not establish that a child understands a word in everyday life.</p><p>Illustrations are reusable original SVG assets. A repeated category entry, alternate spelling, background change, or recolouring is not counted as another object.</p><a class="back" href="vocabulary/catalog.json" download="object-vocabulary-catalog.json">Save the full word-to-picture catalogue ↓</a></details></section>`;skillNav();document.getElementById('vocabBack').onclick=skillHome;document.getElementById('vocabCategory').onchange=e=>{vocabularyLibrary({category:e.target.value,page:0,saved:false});vocabularyWrite(e.target.value?'#vocabulary/category/'+e.target.value:'#vocabulary');};document.getElementById('vocabSearch').oninput=e=>{const value=e.target.value;clearTimeout(vocabularySearchTimer);vocabularySearchTimer=setTimeout(()=>{if(!app.querySelector('.vocabulary-library'))return;vocabularyLibrary({query:value,page:0});const input=document.getElementById('vocabSearch');input.focus({preventScroll:true});input.setSelectionRange(value.length,value.length);},250);};document.getElementById('vocabSaved').onclick=()=>vocabularyLibrary({saved:!f.saved,page:0,category:''});document.getElementById('vocabNames').onclick=()=>vocabularyLibrary({names:!f.names});document.getElementById('vocabPrevious').onclick=()=>{vocabularyLibrary({page:f.page-1});window.scrollTo(0,0);};document.getElementById('vocabNext').onclick=()=>{vocabularyLibrary({page:f.page+1});window.scrollTo(0,0);};const explore=document.getElementById('vocabExplore');if(explore)explore.onclick=()=>vocabularyStart(category.id,'explore');const play=document.getElementById('vocabPlay');if(play)play.onclick=()=>vocabularyStart(category.id,'find');app.querySelectorAll('[data-vocab-open]').forEach(b=>b.onclick=()=>{vocabularyDetail(b.dataset.vocabOpen);vocabularyWrite('#vocabulary/object/'+b.dataset.vocabOpen);});app.querySelectorAll('[data-vocab-save]').forEach(b=>b.onclick=()=>{vocabularySetSaved(b.dataset.vocabSave);vocabularyLibrary();});}
function vocabularyDetail(id){clearTimeout(vocabularySearchTimer);const o=vocabularyObjects.get(id);if(!o){vocabularyLibrary();return;}skillContext=null;app.innerHTML=`<section class="vocabulary-detail"><button class="back" id="vocabDetailBack">← Back to the picture library</button><div class="vocabulary-detail-layout"><div class="vocabulary-large-picture">${vocabularyImage(id)}</div><div><span class="eyebrow">AN EVERYDAY WORD</span><h1>${senEscape(o.label)}</h1><p>Look at the picture together. Say or sign the word, or find it in the child’s usual communication system.</p>${o.aliases.some(w=>w!==o.label)?`<p class="micro">Also listed as: ${o.aliases.filter(w=>w!==o.label).map(senEscape).join(', ')}.</p>`:''}<div class="calm-controls"><button class="primary" id="vocabDetailPlay">Play with this word →</button><button class="secondary" id="vocabDetailSave">${vocabularySaved.includes(id)?'★ Saved':'☆ Save this word'}</button><a class="secondary" href="${o.image}" download="${o.id}.svg">Save this picture ↓</a></div><h2>Where can we find it?</h2><div class="vocabulary-tags">${o.categories.map(cid=>`<button class="secondary" data-vocab-tag="${cid}">${senEscape(vocabularyCategories.get(cid).name)}</button>`).join('')}</div><p class="micro">Try a real object or photograph too. Pictures are examples; everyday things can look different.</p></div></div></section>`;skillNav();document.getElementById('vocabDetailBack').onclick=()=>{vocabularyLibrary();vocabularyWrite('#vocabulary');};document.getElementById('vocabDetailSave').onclick=()=>{vocabularySetSaved(id);vocabularyDetail(id);};document.getElementById('vocabDetailPlay').onclick=()=>vocabularyStart(o.categories[0],'find',id);app.querySelectorAll('[data-vocab-tag]').forEach(b=>b.onclick=()=>{vocabularyLibrary({category:b.dataset.vocabTag,page:0,query:''});vocabularyWrite('#vocabulary/category/'+b.dataset.vocabTag);});window.scrollTo(0,0);}
function vocabularyStart(category,mode='explore',target=null){clearTimeout(vocabularySearchTimer);const ids=vocabularyCategoryIds(category),visit=nextPictureVisit('vocabulary',category);if(ids.length<3)throw Error('Category needs three objects');const offset=visit*3%ids.length,chosen=target||ids[offset];vocabularyState={category,mode,visit,target:chosen,choices:shuffle([chosen,...shuffle(ids.filter(v=>v!==chosen)).slice(0,3)]),selection:null,collection:vocabularySample(category,3,offset),collected:[],current:offset,selectedPair:null,paired:[],feedback:'',done:false,paused:false,names:true};if(mode==='pairs'){const selected=vocabularySample(category,3,offset);vocabularyState.cards=shuffle(selected.flatMap(id=>[{id},{id}]));}if(mode==='sort'){const a=category,number=Number(category),b=category==='011'?'012':number>=11&&number<=20?'021':number>=61&&number<=70?'073':'011',aIds=vocabularyCategoryIds(a),bIds=vocabularyCategoryIds(b),left=shuffle(aIds.filter(id=>!bIds.includes(id))).slice(0,2),right=shuffle(bIds.filter(id=>!aIds.includes(id))).slice(0,2);vocabularyState.groups=[{category:a,ids:left},{category:b,ids:right}];vocabularyState.sortCards=shuffle([...left,...right]);vocabularyState.sorted={};}vocabularyRender();window.scrollTo(0,0);}
function vocabularyFinish(){const s=vocabularyState;if(!s)return;const ids=s.mode==='collect'?s.collection:s.mode==='pairs'?[...new Set(s.cards.map(c=>c.id))]:s.mode==='sort'?s.groups.flatMap(g=>g.ids):[s.target];app.innerHTML=`<section class="game-wrap vocabulary-completion"><span class="eyebrow">WORDS TO TRY IN REAL LIFE</span><h1>A little collection of discoveries.</h1><div class="vocabulary-finished-pictures">${ids.map(id=>`<figure>${vocabularyImage(id)}<figcaption>${senEscape(vocabularyObjects.get(id).label)}</figcaption></figure>`).join('')}</div><p>Find or talk about one familiar example together. Pointing, signing, speech and AAC are all welcome.</p><div class="calm-controls"><button class="secondary" id="vocabAgain">Explore again</button><button class="primary" id="vocabReturn">Back to the course</button><button class="secondary" id="vocabAnotherKind">Try a different kind of play →</button></div></section>`;skillNav();document.getElementById('vocabAgain').onclick=()=>vocabularyStart(s.category,s.mode);document.getElementById('vocabReturn').onclick=()=>{vocabularyState=null;if(skillContext)skillCourse(skillContext.courseId);else vocabularyLibrary({category:s.category});};document.getElementById('vocabAnotherKind').onclick=()=>vocabularyStart(s.category,vocabularyModes[(vocabularyModes.indexOf(s.mode)+1)%vocabularyModes.length]);window.scrollTo(0,0);}
function vocabularySuccess(message){const s=vocabularyState;if(s.done)return;s.done=true;s.feedback=message;vocabularyRender();setTimeout(()=>{if(vocabularyState===s&&s.done&&!s.paused&&app.querySelector('.vocabulary-play'))vocabularyFinish();},1000);}
function vocabularySelect(id){const s=vocabularyState;if(s.done)return;s.selection=id;if(id===s.target)vocabularySuccess('Great! '+vocabularyObjects.get(id).label+'.');else{s.feedback='Let’s look at another picture. You can try again.';vocabularyRender();}}
function vocabularyCollect(id){const s=vocabularyState;if(s.done)return;if(!s.collection.includes(id)){s.feedback='That one can stay here. Our picture list shows what we need.';vocabularyRender();return;}if(!s.collected.includes(id))s.collected.push(id);if(s.collected.length===s.collection.length)vocabularySuccess('Great! Our picture collection is complete.');else{s.feedback=vocabularyObjects.get(id).label+' is in our collection.';vocabularyRender();}}
function vocabularyPair(index){const s=vocabularyState;if(s.done||s.paired.includes(index))return;if(s.selectedPair===null){s.selectedPair=index;s.feedback='Choose or drag to the picture’s partner.';vocabularyRender();return;}if(s.selectedPair===index){s.selectedPair=null;vocabularyRender();return;}const first=s.selectedPair;s.selectedPair=null;if(s.cards[first].id===s.cards[index].id){s.paired.push(first,index);if(s.paired.length===s.cards.length)vocabularySuccess('Great! Three picture partners.');else{s.feedback='A pair of '+vocabularyObjects.get(s.cards[index].id).label+' pictures.';vocabularyRender();}}else{s.feedback='Look at the shape and details. Another picture is its partner.';vocabularyRender();}}
function vocabularySort(id,group){const s=vocabularyState;if(s.done||s.sorted[id]!==undefined)return;if(s.groups[group].ids.includes(id)){s.sorted[id]=group;s.selection=null;if(Object.keys(s.sorted).length===s.sortCards.length)vocabularySuccess('Great! Two little collections.');else{s.feedback='You added '+vocabularyObjects.get(id).label+'.';vocabularyRender();}}else{s.feedback='Compare this picture with the two collections. Try the other one.';vocabularyRender();}}
function vocabularyRender(){const s=vocabularyState;if(!s)return;if(s.mode==='explore')s.target=vocabularyCategoryIds(s.category)[s.current%vocabularyCategoryIds(s.category).length];const category=vocabularyCategories.get(s.category),activeWords=s.mode==='collect'?s.collection:s.mode==='pairs'?[...new Set(s.cards.map(c=>c.id))]:s.mode==='sort'?s.groups.flatMap(g=>g.ids):[s.target];let body='',instruction='';const pictureButton=(id,attr,selected=false)=>`<button class="vocabulary-choice ${selected?'selected':''}" ${attr} aria-label="${senEscape(vocabularyObjects.get(id).label)}" ${s.done?'disabled':''}>${vocabularyImage(id)}${s.names?`<span>${senEscape(vocabularyObjects.get(id).label)}</span>`:''}</button>`;
 if(s.mode==='explore'){const ids=vocabularyCategoryIds(s.category);s.target=ids[s.current%ids.length];instruction='Meet one word. Look, name it together, or find a real example.';body=`<div class="vocabulary-flashcard">${vocabularyImage(s.target)}<h2 ${s.names?'':'hidden'}>${senEscape(vocabularyObjects.get(s.target).label)}</h2></div><div class="calm-controls"><button class="secondary" id="vocabWordPrev">← Previous word</button><button class="primary" id="vocabWordNext">Meet another word →</button></div>`;}
 if(s.mode==='find'){instruction='Find the '+vocabularyObjects.get(s.target).label+'.';body=`<div class="vocabulary-choice-home tp-answer-pad ${s.selection?'has-choice':''}" id="vocabChoiceHome" role="group" aria-label="Your choice">${s.selection?`${vocabularyImage(s.selection)}<b>${senEscape(vocabularyObjects.get(s.selection).label)}</b>`:'<span>Drag a picture here, or tap it below.</span>'}</div><div class="vocabulary-options">${s.choices.map(id=>pictureButton(id,`data-vocab-choice="${id}"`,s.selection===id)).join('')}</div>`;}
 if(s.mode==='collect'){const extra=vocabularySample(s.category,20,s.current).filter(id=>!s.collection.includes(id)).slice(0,2);instruction='Make a collection of the three pictures on our list.';body=`<div class="vocabulary-picture-list" aria-label="Our picture list">${s.collection.map(id=>`<span class="${s.collected.includes(id)?'collected':''}">${vocabularyImage(id)}<small>${senEscape(vocabularyObjects.get(id).label)}</small></span>`).join('')}</div><div class="vocabulary-collection-board" id="vocabCollection" role="group" aria-label="Our picture collection">${s.collection.map((id,i)=>`<div>${s.collected.includes(id)?vocabularyImage(id):`<span>${i+1}</span>`}</div>`).join('')}</div><div class="vocabulary-options">${[...s.collection,...extra].filter(id=>!s.collected.includes(id)).map(id=>pictureButton(id,`data-vocab-collect="${id}"`)).join('')}</div>`;}
 if(s.mode==='pairs'){instruction='Find each picture’s partner. All the pictures stay face up.';body=`<div class="vocabulary-pair-board">${s.cards.map((c,i)=>`<button class="vocabulary-choice ${s.selectedPair===i?'selected':''} ${s.paired.includes(i)?'paired':''}" data-vocab-pair="${i}" aria-label="${senEscape(vocabularyObjects.get(c.id).label)}${s.paired.includes(i)?', paired':''}" ${s.paired.includes(i)||s.done?'disabled':''}>${vocabularyImage(c.id)}${s.paired.includes(i)?'<span class="vocabulary-pair-tick">✓</span>':''}</button>`).join('')}</div>`;}
 if(s.mode==='sort'){instruction='Make two collections. A grown-up can name the groups and show an example.';body=`<div class="vocabulary-sort-homes">${s.groups.map((g,i)=>`<button class="vocabulary-sort-home" data-vocab-home="${i}" aria-label="${senEscape(g.label||vocabularyCategories.get(g.category).name)}"><h2>${senEscape(g.label||vocabularyCategories.get(g.category).name)}</h2><div class="vocabulary-sort-model">${g.ids.map(id=>vocabularyImage(id)).join('')}</div><div class="vocabulary-sorted">${Object.entries(s.sorted).filter(([,v])=>v===i).map(([id])=>vocabularyImage(id)).join('')}</div><small>${Object.values(s.sorted).includes(i)?'Keep going, or change your choice.':'Drop a matching picture here, or tap one then this collection.'}</small></button>`).join('')}</div><div class="vocabulary-options">${s.sortCards.filter(id=>s.sorted[id]===undefined).map(id=>pictureButton(id,`data-vocab-sort="${id}"`,s.selection===id)).join('')}</div>`;}
 app.innerHTML=`<div class="play-top"><button class="back" id="vocabPlayBack">← Back to the course</button><span class="together-note">♧ Play together</span></div><section class="game-wrap vocabulary-play"><span class="eyebrow">${senEscape(category.name)} · ${vocabularyModeLabels[s.mode]}</span><h1>${s.mode==='explore'?'A world of everyday words':vocabularyModeLabels[s.mode]}</h1><p class="play-invitation">${senEscape(instruction)}</p><div class="vocabulary-game-board">${body}</div><p class="vocabulary-feedback ${s.done?'success':''}" role="status" aria-live="polite">${senEscape(s.feedback||'Point, tap, or drag. There is no hurry.')}</p><div class="vocabulary-game-controls"><button class="secondary" id="vocabGameNames">${s.names?'Hide names':'Show names'}</button><button class="secondary" id="vocabGameSave">${activeWords.every(id=>vocabularySaved.includes(id))?'★ Saved':activeWords.length>1?'☆ Save these words':'☆ Save this word'}</button>${s.mode!=='explore'?`<button class="back" id="vocabGamePause">${s.paused?'Resume automatic progress':'Pause automatic progress'}</button>`:''}<button class="secondary" id="vocabGameDone">${s.done?'Continue →':'Finish for now'}</button></div><details class="quiet-notes"><summary>A little help for grown-ups</summary><p>Model each word before asking the child to recognise it. Use speech, signs, pointing, or their usual AAC. Looking together or choosing with support is welcome. There is no automatic judgement of spoken naming.</p><p>${s.mode==='sort'?'These are examples for our two collections, not a rule that an object can only belong in one place. Name or demonstrate the categories first.':'Use a smaller selection or try a real object if the pictures are unfamiliar.'}</p><p>This is supplementary vocabulary practice, not a diagnostic test or a replacement for language or communication support.</p></details></section>`;skillNav();const bind=(id,fn)=>{const b=document.getElementById(id);if(b)b.onclick=fn;};bind('vocabPlayBack',()=>{vocabularyState=null;if(skillContext)skillCourse(skillContext.courseId);else vocabularyLibrary({category:s.category});});bind('vocabWordNext',()=>{s.current++;s.feedback='';vocabularyRender();});bind('vocabWordPrev',()=>{s.current=(s.current-1+vocabularyCategoryIds(s.category).length)%vocabularyCategoryIds(s.category).length;vocabularyRender();});bind('vocabGameNames',()=>{s.names=!s.names;vocabularyRender();});bind('vocabGameSave',()=>{for(const id of activeWords)if(!vocabularySaved.includes(id))vocabularySetSaved(id);vocabularyRender();});bind('vocabGamePause',()=>{s.paused=!s.paused;if(s.done&&!s.paused)vocabularyFinish();else vocabularyRender();});bind('vocabGameDone',vocabularyFinish);app.querySelectorAll('[data-vocab-choice]').forEach(b=>b.onclick=()=>vocabularySelect(b.dataset.vocabChoice));app.querySelectorAll('[data-vocab-collect]').forEach(b=>b.onclick=()=>vocabularyCollect(b.dataset.vocabCollect));app.querySelectorAll('[data-vocab-pair]').forEach(b=>b.onclick=()=>vocabularyPair(+b.dataset.vocabPair));app.querySelectorAll('[data-vocab-sort]').forEach(b=>b.onclick=()=>{s.selection=b.dataset.vocabSort;s.feedback='Choose the collection for this picture.';vocabularyRender();});app.querySelectorAll('[data-vocab-home]').forEach(b=>b.onclick=()=>{if(s.selection)vocabularySort(s.selection,+b.dataset.vocabHome);});}
// Broaden the existing adult-supported noun games without changing checked speech-sound examples.
const vocabularyOriginalAdultTask=makeAdultTask;
makeAdultTask=function(key,index,round,seed=0){const task=vocabularyOriginalAdultTask(key,index,round,seed);if(key==='words'&&index<5&&practiceRounds(3)===1){const groups=[['004','005','018','019'],['021','022','023','024','025'],['011','012','013','014','015','017'],['041','042','043','044','045','046','047','048','049','050'],['009','061','086','090']],ids=[...new Set(groups[index].flatMap(vocabularyCategoryIds))],target=ids[(seed*3+round)%ids.length],others=shuffle(ids.filter(id=>id!==target)).slice(0,2);task.options=shuffle([{id:'answer',picture:'vocab:'+target},...others.map((id,i)=>({id:'other'+i,picture:'vocab:'+id}))]);task.answer=['answer'];task.adult='Show me the '+vocabularyObjects.get(target).label+'.';task.teach='Explore and name the pictures together before choosing. Accept the child’s usual communication.';task.explanation='We found a picture of '+vocabularyObjects.get(target).label+'.';}return task;};
TouchPlay.register(bind=>{if(!app.querySelector('.vocabulary-play')||!vocabularyState||vocabularyState.done)return;const s=vocabularyState;app.querySelectorAll('[data-vocab-choice]').forEach(b=>bind(b,{targets:()=>[document.getElementById('vocabChoiceHome')],drop:()=>vocabularySelect(b.dataset.vocabChoice)}));app.querySelectorAll('[data-vocab-collect]').forEach(b=>bind(b,{targets:()=>[document.getElementById('vocabCollection')],drop:()=>vocabularyCollect(b.dataset.vocabCollect)}));app.querySelectorAll('[data-vocab-pair]:not(:disabled)').forEach(b=>bind(b,{targets:()=>[...app.querySelectorAll('[data-vocab-pair]:not(:disabled)')].filter(v=>v!==b),drop:target=>{s.selectedPair=+b.dataset.vocabPair;vocabularyPair(+target.dataset.vocabPair);}}));app.querySelectorAll('[data-vocab-sort]').forEach(b=>bind(b,{targets:()=>[...app.querySelectorAll('[data-vocab-home]')],drop:target=>vocabularySort(b.dataset.vocabSort,+target.dataset.vocabHome)}));});
